raw = json.load(open(SP + 'gram_raw.json'))
# HSK6: một mục "Mẫu cố định" bị ngắt sang trang sau, nối lại
r6 = raw['6']
for i in range(len(r6) - 1):
    if r6[i]['g'] == r6[i+1]['g'] == 'Mẫu cố định' and r6[i]['c'].endswith('（没）'):
        r6[i]['c'] += r6[i+1]['c']; del r6[i+1]; break
FIX = {'Chuyển折': 'Chuyển hướng'}
def title(r):
    g, t, s = r['g'], FIX.get(r['t'], r['t']), r['s']
    if g in ('Từ loại', 'Hình vị'): return s or t
    if not t: return g
    return f"{g}: {(s or t)[0].lower() + (s or t)[1:]}" if g not in ('Câu ghép',) else f"Câu ghép {t[0].lower() + t[1:]}"
levels = {}
for L in range(1, 7):
    rows = raw[str(L)]
    assert len(rows) == len(E[L]), (L, len(rows), len(E[L]))
    pts = []
    for r, (d, zh, vi, k) in zip(rows, E[L]):
        assert k in zh, (L, k, zh)
        pts.append({'t': title(r), 'c': r['c'].replace('  ', ' '), 'd': d, 'zh': zh, 'vi': vi, 'k': k})
    levels[str(L)] = pts
old = json.load(open(APP + 'data/grammar.json'))
out = {'levels': levels, 'notes': old.get('notes', {}), 'ex': old.get('ex', {}),
       'src': 'Đề cương ngữ pháp theo tài liệu HSK 3.0 (11-2025) của cô Trần Mỹ Hạnh, Meiday Chinese (facebook.com/tranmyhanh101198). Giải thích ngắn và câu ví dụ do web soạn thêm; ghi chú và bài tập tổng hợp HSK 1–3 theo tài liệu ngữ pháp trước đây.'}
json.dump(out, open(APP + 'data/grammar.json', 'w'), ensure_ascii=False, separators=(',', ':'))
print({L: len(v) for L, v in levels.items()})
